// Geminiの応答(JSON想定)を解析し、元の取引データと結合する
// 解析に失敗した場合は安全側に倒してREQUIRES_REVIEW扱いにする
const originalDeals = $('Split deals into items').all();

return items.map((item, idx) => {
  const deal = originalDeals[idx] ? originalDeals[idx].json : {};
  let judgement = 'REQUIRES_REVIEW';
  let comment = 'AIの応答を解析できませんでした。手動で確認してください。';

  try {
    const raw = item.json.candidates[0].content.parts[0].text;
    const cleaned = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    judgement = String(parsed.judgement || '').toUpperCase().includes('OK') ? 'OK' : 'REQUIRES_REVIEW';
    comment = parsed.comment || raw;
  } catch (e) {
    // パース失敗時はREQUIRES_REVIEWのまま（見落とし防止）
  }

  return {
    json: {
      ...deal,
      judgement,
      ai_comment: comment
    }
  };
});
